<?php require_once 'includes/auth.php';if(customer_logged_in()){header('Location: account.php');exit;}$e=[];if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$em=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$ad=trim($_POST['address']??'');$pw=$_POST['password']??'';$cp=$_POST['confirm_password']??'';if(!$n)$e[]='Name is required.';if(!filter_var($em,FILTER_VALIDATE_EMAIL))$e[]='Valid email is required.';if(strlen($pw)<8)$e[]='Password must be at least 8 characters.';if($pw!==$cp)$e[]='Passwords do not match.';$s=db()->prepare('SELECT id FROM customers WHERE email=?');$s->execute([$em]);if($s->fetch())$e[]='Email already registered.';if(!$e){$s=db()->prepare('INSERT INTO customers(name,email,phone,address,password_hash)VALUES(?,?,?,?,?)');$s->execute([$n,$em,$ph,$ad,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['customer_id']=db()->lastInsertId();header('Location: account.php');exit;}}$title='Register - '.APP_NAME;include 'includes/header.php';?><h1>Create Account</h1><form class="form" method="post"><?php foreach($e as $x):?><div class="notice error"><?=htmlspecialchars($x)?></div><?php endforeach;?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone" placeholder="2547XXXXXXXX" required></label><label>Address<textarea name="address"></textarea></label><label>Password<input type="password" name="password" required></label><label>Confirm Password<input type="password" name="confirm_password" required></label><button class="btn">Create Account</button></form><?php include 'includes/footer.php';?>